BEGIN;
CREATE EXTENSION IF NOT EXISTS pgtap WITH SCHEMA extensions;
SET LOCAL search_path=extensions,pg_catalog,public;
SELECT plan(22);
SELECT ok(to_regclass('app_private.admission_application_policy_snapshots') IS NOT NULL,'private application-scoped published-policy history exists');
SELECT ok((SELECT count(*)=1 FROM pg_constraint WHERE conrelid='app_private.admission_applications'::regclass AND conname='db03_policy_snapshot_application_scope_key' AND contype='u' AND cardinality(conkey)=3),'application exposes School and Academic Year scoped reference key');
SELECT ok((SELECT count(*)=1 FROM pg_constraint WHERE conrelid='app_private.admission_policy_versions'::regclass AND conname='db03_policy_snapshot_policy_profiles_key' AND contype='u' AND cardinality(conkey)=4),'policy exposes School and both numbering-profile references');
SELECT ok((SELECT count(*)=1 FROM pg_constraint WHERE conrelid='app_private.admission_application_policy_snapshots'::regclass AND contype='f' AND confrelid='app_private.admission_applications'::regclass AND cardinality(conkey)=3),'source must match application's School and Academic Year');
SELECT ok((SELECT count(*)=1 FROM pg_constraint WHERE conrelid='app_private.admission_application_policy_snapshots'::regclass AND contype='f' AND confrelid='app_private.admission_policy_versions'::regclass AND cardinality(conkey)=4),'both selected numbering profiles must be the policy's actual profiles');
SELECT ok((SELECT count(*)=1 FROM pg_constraint WHERE conrelid='app_private.admission_application_policy_snapshots'::regclass AND contype='f' AND confrelid='app_private.admission_application_policy_snapshots'::regclass AND cardinality(conkey)=2),'prior selection revision must belong to the same application');
SELECT ok((SELECT count(*)=1 FROM pg_constraint WHERE conrelid='app_private.admission_application_policy_snapshots'::regclass AND contype='f' AND confrelid='app_private.command_receipts'::regclass),'every source has an authenticated-command receipt reference');
SELECT ok((SELECT count(*)=1 FROM pg_constraint WHERE conrelid='app_private.admission_application_policy_snapshots'::regclass AND contype='c' AND pg_get_constraintdef(oid) LIKE '%octet_length(published_configuration_hash)%'),'recorded configuration hash must be 32 bytes');
SELECT ok((SELECT count(*)>=1 FROM pg_constraint WHERE conrelid='app_private.admission_application_policy_snapshots'::regclass AND contype='c' AND pg_get_constraintdef(oid) LIKE '%revision%'),'source revision and supersedes shape guarded');
SELECT ok((SELECT count(*)=1 FROM pg_constraint WHERE conrelid='app_private.admission_application_policy_snapshots'::regclass AND conname='db03_policy_snapshot_application_revision' AND contype='u'),'one retained revision number per application');
SELECT ok((SELECT count(*)=1 FROM pg_constraint WHERE conrelid='app_private.admission_application_policy_snapshots'::regclass AND conname='db03_policy_snapshot_same_application_key' AND contype='u'),'same-application self-FK supported');
SELECT ok((SELECT count(*)=1 FROM pg_constraint WHERE conrelid='app_private.admission_application_policy_snapshots'::regclass AND contype='u' AND cardinality(conkey)=1 AND pg_get_constraintdef(oid) LIKE '%supersedes_id%'),'selection cannot be superseded by two successor rows');
SELECT ok((SELECT count(*)=1 FROM pg_class WHERE oid='app_private.admission_application_policy_snapshots'::regclass AND relrowsecurity AND relforcerowsecurity),'policy selections enforce RLS');
SELECT ok(NOT has_table_privilege('authenticated','app_private.admission_application_policy_snapshots','INSERT') AND NOT has_table_privilege('service_role','app_private.admission_application_policy_snapshots','INSERT') AND NOT has_table_privilege('schoolos_workflow_executor','app_private.admission_application_policy_snapshots','INSERT'),'no client, service or workflow writer grants');
SELECT ok((SELECT count(*)=1 FROM pg_policies WHERE schemaname='app_private' AND tablename='admission_application_policy_snapshots' AND policyname='db03_policy_snapshot_owner'),'owner-only policy installed');
SELECT ok((SELECT count(*)=1 FROM pg_trigger WHERE tgname='db03_policy_snapshot_mutation_disabled' AND NOT tgisinternal AND tgenabled='O'),'row mutations universally denied');
SELECT ok((SELECT count(*)=1 FROM pg_trigger WHERE tgname='db03_policy_snapshot_no_truncate' AND NOT tgisinternal AND tgenabled='O'),'history truncation universally denied');
SELECT throws_ok($q$INSERT INTO app_private.admission_application_policy_snapshots DEFAULT VALUES$q$,'P0001','DB03 admission policy snapshot writer unavailable','cannot fabricate a binding');
SELECT ok(to_regprocedure('app.bind_admission_application_policy(uuid,uuid)') IS NULL,'no client policy selection command');
SELECT ok((SELECT count(*)=1 FROM pg_constraint WHERE conrelid='app_private.admission_applications'::regclass AND conname='db03_unsubmitted_policy_null'),'existing draft policy projection remains fail closed');
SELECT ok(to_regprocedure('app_private.db03_render_admission_number(text,text,text,date,integer,bigint,bigint)') IS NOT NULL,'P43 canonical formatter preserved');
SELECT ok(to_regprocedure('app.approve_admission_principal(uuid,bigint,uuid,uuid)') IS NULL,'Principal approval and D1 Student creation remain disabled');
SELECT * FROM finish();
ROLLBACK;
